const BIRTH_NEIGHBOR_COUNT = 3;

const neighborsOf = ([x, y]: Cell): Cell[] =>
  [-1, 0, 1].flatMap((dx) =>
    [-1, 0, 1]
      .filter((dy) => !(dx === 0 && dy === 0))
      .map((dy): Cell => [x + dx, y + dy]),
  );

const isBorn = (cell: Cell, liveCells: Cell[]): boolean =>
  !liveCells.some((live) => isSameCell(cell, live)) &&
  countLiveNeighbors(cell, liveCells) === BIRTH_NEIGHBOR_COUNT;

export function nextGeneration(liveCells: Cell[]): Cell[] {
  const survivors = liveCells.filter((cell) => survives(cell, liveCells));

  const births = liveCells
    .flatMap(neighborsOf)
    .filter((cell) => isBorn(cell, liveCells))
    .filter(
      (cell, index, candidates) =>
        candidates.findIndex((other) => isSameCell(cell, other)) === index,
    );

  return [...survivors, ...births];
}

