export type Cell = [number, number];

const SURVIVAL_NEIGHBOR_COUNTS = [2, 3];

const isSameCell = ([x, y]: Cell, [otherX, otherY]: Cell): boolean =>
  x === otherX && y === otherY;

const isAdjacent = ([x, y]: Cell, [otherX, otherY]: Cell): boolean =>
  Math.abs(x - otherX) <= 1 && Math.abs(y - otherY) <= 1;

const isNeighbor = (cell: Cell, other: Cell): boolean =>
  isAdjacent(cell, other) && !isSameCell(cell, other);

const countLiveNeighbors = (cell: Cell, liveCells: Cell[]): number =>
  liveCells.filter((other) => isNeighbor(cell, other)).length;

const survives = (cell: Cell, liveCells: Cell[]): boolean =>
  SURVIVAL_NEIGHBOR_COUNTS.includes(countLiveNeighbors(cell, liveCells));

export function nextGeneration(liveCells: Cell[]): Cell[] {
  return liveCells.filter((cell) => survives(cell, liveCells));
}

